function sessionPanel(){const user=workspaceSession.user;if(user)return `<div class="workspace-account-kicker">PAPERKNOW ACCOUNT</div><div class="hub-account-summary">${avatar()}<div><h2>${esc(accountName())}</h2><p>${esc(accountIdentity())}</p></div>${badge('已登录','mint')}</div><p class="workspace-account-description">使用同一个账户登录 PaperKnow，管理服务端项目、文件与任务。</p><div class="workspace-account-actions"><a class="btn primary" href="/service.html">进入服务工作台 ${icon('arrow',16)}</a><button class="btn secondary" type="button" data-session-logout>退出登录</button></div><p class="workspace-account-note">当前浏览器中的研究草稿单独保存，不会因登录或退出而自动同步、转移或删除。</p>`;
const unavailable=workspaceSession.status==='error';return `<div class="workspace-account-kicker">PAPERKNOW ACCOUNT</div><div class="workspace-account-guest"><span class="workspace-account-symbol">${icon('user',26)}</span><div><h2>${unavailable?'暂时无法连接账户':'登录你的 PaperKnow'}</h2><p>${unavailable?'本地研究空间仍可继续使用，请稍后重新连接。':'支持邮箱或手机号，密码或验证码登录。'}</p></div></div><div class="workspace-account-actions"><a class="btn primary" href="${esc(authHref())}">登录账户 ${icon('arrow',16)}</a><a class="btn secondary" href="${esc(authHref('register'))}">注册账户</a>${unavailable?'<button class="text-btn" type="button" data-session-retry>重新连接</button>':''}</div><p class="workspace-account-note">已有的本地草稿会保留在当前浏览器。登录后，可另行使用服务端项目与任务。</p>`;}
